package io.github.diodeme.ji.artifact;

import java.util.Arrays;

/** Zero-based resumable upload chunk. */
public record UploadChunk(int index, byte[] bytes) {
    public UploadChunk {
        if (index < 0) throw new IllegalArgumentException("chunk index must be non-negative");
        bytes = Arrays.copyOf(bytes, bytes.length);
    }

    @Override public byte[] bytes() { return Arrays.copyOf(bytes, bytes.length); }
}
